-- =====================================================================
-- Trein -- generic multi-category catalog sample data.
--
-- Replaces the old sample_data_300.sql (100 phone / 100 laptop / 100
-- headphone rows across three bespoke tables) with rows in ONE generic
-- `products` table covering 12 categories (96 rows total), matching the
-- schema the backend's app/catalog package expects.
--
-- `online_link` values point to the static product website (localhost:3000).
-- with real product URLs before this goes anywhere near real customers.
-- `offline_availability` values reference the example store names in
-- backend/app/data/stores.json -- edit both together.
--
-- If you already have data in the old phone/laptop/headphone tables from
-- a previous version of this project, see migrate_to_products_table.sql
-- (sql/legacy/) to port it into this schema instead of starting over.
--
-- Usage:
--   mysql -u <username> -p retail_shop < sql/seed/01_products.sql
--
-- Then run seed/02_customer_feedback.sql for review text. The backend
-- re-indexes the catalog automatically on its next start.
-- =====================================================================

CREATE TABLE IF NOT EXISTS products (
    id                    INT AUTO_INCREMENT PRIMARY KEY,
    category              VARCHAR(100) NOT NULL,
    name                  VARCHAR(255) NOT NULL,
    brand                 VARCHAR(100) NOT NULL,
    price                 INT NOT NULL,
    mrp                   INT NULL,
    units_available       INT NULL,
    rating                DECIMAL(2,1) NULL,
    online_link           VARCHAR(500) NULL,
    offline_availability  VARCHAR(255) NULL,
    description           VARCHAR(500) NULL,
    customer_feedback     TEXT NULL,
    attributes            JSON NULL,
    -- Written back by the backend's catalog sync (see add_ingestion_status.sql).
    ingestion_status          VARCHAR(20) NULL,
    ingestion_missing_fields  JSON NULL,
    created_at            TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_products_category (category),
    INDEX idx_products_ingestion_status (ingestion_status)
);

-- ---------------------------------------------------------------------
-- 96 products across 12 categories
-- ---------------------------------------------------------------------
